"""Export native captures in two layouts. Keys are stable logical parameter coordinates."""
import argparse,pathlib,json,numpy as np,torch
p=argparse.ArgumentParser();p.add_argument("input");p.add_argument("output");p.add_argument("--layout",choices=["flat","split"],required=True);a=p.parse_args()
r=torch.load(a.input,weights_only=True);out=pathlib.Path(a.output);out.mkdir(parents=True,exist_ok=True);manifest=[]
for row in r:
    values={"loss":np.asarray(row["loss"])}
    for stage in ["grads","updates","parameters"]:
        for name,v in row[stage].items():values[stage+"/"+name]=v.numpy()
    if a.layout=="flat":
        filename=f"step-{row['step']}.npz";np.savez(out/filename,**values)
        manifest.append({"step":row['step'],"file":filename,"keys":list(values)})
    else:
        for i,(key,value) in enumerate(values.items()):
            filename=f"s{row['step']}-tensor-{i}.npy";np.save(out/filename,value)
            manifest.append({"step":row['step'],"key":key,"file":filename})
(out/"index.json").write_text(json.dumps({"layout":a.layout,"entries":manifest},indent=2))
